===== README.md =====
# CPU policy agent

`driver.py` is the collected JSON entry point. `syntax.py` defines the public language and input bounds without evaluating predicates. `compiler/compiler.py` contains the existing FAdo predicate constructors and serial policy reduction. `ebpf/create_dfa.py` compiles and exports useful states. `ebpf/helper.py` installs transition cells in a memory backend and has an incomplete Agent interface.

Implement the complete versioned control-plane contract in `/workspace/PROTOCOL.md`. Kernel attachment, service deployment and packet capture are outside this project. You may edit every file in this directory and add ordinary files. The offline packages are already supplied; do not install dependencies. Run `python3 /workspace/launch.py < request.json` and `python3 /workspace/public_check.py` as a nonroot user. The starter is intentionally incomplete and is expected to fail the final contract.
===== driver.py =====
"""JSON batch entry point; policy/runtime modules implement the system."""
import json,math,re,sys
from ebpf.helper import Agent
from syntax import parse
U32=4294967295
LIMITS={'images':16,'cells':262144,'units':1024,'contexts':32768,'connections':4096,'packets':32768,'files':8192}
NAME=re.compile(r'[A-Za-z][A-Za-z0-9]{0,23}\Z')
SCHEMA={
 'stage':{'epoch':'positive','policy':'text'},'commit':{'epoch':'positive'},'retire':{'epoch':'positive'},
 'spawn':{'unit':'unit','service':'name'},'clone':{'parent':'unit','child':'unit'},'exit':{'unit':'unit'},
 'begin':{'unit':'unit','rid':'positive'},'finish':{'unit':'unit','rid':'positive'},
 'open':{'connection':'pair'},'close':{'connection':'pair'},
 'send':{'unit':'unit','rid':'positive','connection':'pair','stream':'positive','destination':'name'},
 'recv':{'unit':'unit','rid':'positive','connection':'pair','stream':'positive','wire':'wire'},
 'store':{'unit':'unit','rid':'positive','file':'pair'},'load':{'unit':'unit','rid':'positive','file':'pair'},
 'unlink':{'file':'pair'},'inspect':{}}
class Invalid(ValueError):pass

def require(ok):
 if not ok:raise Invalid()

def integer(v,lo=1,hi=U32):return type(v) is int and lo<=v<=hi

def typed(v,kind):
 if kind=='positive':return integer(v)
 if kind=='name':return type(v) is str and NAME.fullmatch(v) is not None
 if kind=='text':
  if type(v) is not str:return False
  v.encode('utf-8')
  return True
 if kind=='wire':return v is None or type(v) is str and len(v)<=96
 if kind=='pair':return type(v) is list and len(v)==2 and all(integer(x) for x in v)
 if kind=='unit':return type(v) is list and len(v)==3 and integer(v[0],0) and integer(v[1]) and integer(v[2])
 return False

def validate(job):
 require(type(job) is dict and set(job)=={'services','limits','events'})
 services=job['services'];limits=job['limits'];events=job['events']
 require(type(services) is list and 1<=len(services)<=16)
 names=set();labels=set()
 for service in services:
  require(type(service) is dict and set(service)=={'name','label'})
  require(typed(service['name'],'name') and integer(service['label'],1,U32-1))
  require(service['name'] not in names and service['label'] not in labels)
  names.add(service['name']);labels.add(service['label'])
 require(type(limits) is dict and set(limits)==set(LIMITS))
 for k,v in limits.items():require(integer(v,1,LIMITS[k]))
 require(type(events) is list and len(events)<=200000)
 for e in events:
  require(type(e) is dict and type(e.get('op')) is str and e['op'] in SCHEMA)
  fields=SCHEMA[e['op']];require(set(e)==set(fields)|{'op'})
  for k,kind in fields.items():require(typed(e[k],kind))
 atoms=symbols=0
 for e in events:
  if e['op']=='stage':
   try:
    tree,a,s=parse(e['policy']);atoms+=a;symbols+=s
   except Exception:pass
 return len(events),sum(len(e['policy'].encode('utf-8')) for e in events if e['op']=='stage'),sum(e['op']=='stage' for e in events),atoms,symbols

def unique(pairs):
 d={}
 for k,v in pairs:
  require(k not in d);d[k]=v
 return d

def invalid_constant(text):raise Invalid()

def float_number(text):
 v=float(text);require(math.isfinite(v));return v

def check_json_nesting(text):
 depth=0;quoted=False;escaped=False
 for char in text:
  if quoted:
   if escaped:escaped=False
   elif char=='\\':escaped=True
   elif char=='"':quoted=False
  elif char=='"':quoted=True
  elif char in '[{':
   depth+=1;require(depth<=64)
  elif char in ']}':
   depth-=1;require(depth>=0)
 require(depth==0 and not quoted)

def solve(data):
 try:
  require(len(data)<=24*1024**2)
  text=data.decode('utf-8');check_json_nesting(text)
  request=json.loads(text,object_pairs_hook=unique,parse_constant=invalid_constant,parse_float=float_number)
  require(type(request) is dict and set(request)=={'jobs'} and type(request['jobs']) is list and len(request['jobs'])<=4)
 except Exception:return {'error':'invalid'}
 results=[];total_events=0;total_policy_bytes=0;total_stages=0;total_rules=0;total_symbols=0
 validity=[]
 for job in request['jobs']:
  try:
   count,size,stages,rules,symbols=validate(job);total_events+=count;total_policy_bytes+=size;total_stages+=stages;total_rules+=rules;total_symbols+=symbols;validity.append(True)
  except Exception:validity.append(False)
 if total_events>200000 or total_policy_bytes>8*1024**2 or total_stages>16 or total_rules>32768 or total_symbols>65536:return {'error':'invalid'}
 for job,valid in zip(request['jobs'],validity):
  if not valid:results.append({'error':'invalid'});continue
  agent=Agent(job['services'],job['limits'])
  results.append({'events':[agent.event(e) for e in job['events']]})
 return {'results':results}

if __name__=='__main__':
 try:result=solve(sys.stdin.buffer.read(24*1024**2+1))
 except Exception:raise
 sys.stdout.write(json.dumps(result,separators=(',',':'),ensure_ascii=True)+'\n')
